// Generated by scripts/build-native-engine.cjs from the existing calendar functions.
    const heavenlyStems = ['甲', '乙', '丙', '丁', '戊', '己', '庚', '辛', '壬', '癸'];
    const earthlyBranches = ['子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥'];
    const stemKorean = ['갑', '을', '병', '정', '무', '기', '경', '신', '임', '계'];
    const branchKorean = ['자', '축', '인', '묘', '진', '사', '오', '미', '신', '유', '술', '해'];
    const weekDays = ['일요일', '월요일', '화요일', '수요일', '목요일', '금요일', '토요일'];

    const SolarManager = window.SajuCalendar;

    function getElementOfCharacter(char) {
        if (['甲', '乙', '寅', '卯'].includes(char)) return 'wood';
        if (['丙', '丁', '巳', '午'].includes(char)) return 'fire';
        if (['戊', '己', '辰', '戌', '丑', '未'].includes(char)) return 'earth';
        if (['庚', '辛', '申', '酉'].includes(char)) return 'metal';
        if (['壬', '癸', '亥', '子'].includes(char)) return 'water';
        return 'earth';
    }

    function getJulianDayNumber(year, month, day) {
        const a = Math.floor((14 - month) / 12); const y = year + 4800 - a; const m = month + 12 * a - 3;
        return day + Math.floor((153 * m + 2) / 5) + 365 * y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) - 32045;
    }

    function getYearPillar(year, month, day, hour, min) {
        const birthTime = SolarManager.instant(year, month, day, hour, min);
        const ipchun = SolarManager.getJeolDateTime(year, '입춘');
        let effectiveYear = year;
        if (ipchun && birthTime < ipchun) effectiveYear = year - 1;
        const cycle = ((effectiveYear - 4) % 60 + 60) % 60;
        return { stemIdx: cycle % 10, branchIdx: cycle % 12 };
    }

    function getMonthPillar(year, month, day, hour, min, yearStemIdx) {
        const birthTime = SolarManager.instant(year, month, day, hour, min);
        const jeols = ['', '소한', '입춘', '경칩', '청명', '입하', '망종', '소서', '입추', '백로', '한로', '입동', '대설'];
        let branchIdx = 0;
        let jeolTime = SolarManager.getJeolDateTime(year, jeols[month]);
        branchIdx = (!jeolTime || birthTime < jeolTime) ? (month - 1) % 12 : month % 12;
        const tigerMonthStemByYearStem = [2, 4, 6, 8, 0, 2, 4, 6, 8, 0];
        const offsetFromTiger = (branchIdx - 2 + 12) % 12;
        return { stemIdx: (tigerMonthStemByYearStem[yearStemIdx] + offsetFromTiger) % 10, branchIdx };
    }

    function getDayPillar(year, month, day) {
        const jdn = getJulianDayNumber(year, month, day);
        const cycle = (jdn + 49) % 60;
        return { stemIdx: cycle % 10, branchIdx: cycle % 12 };
    }

    function makePillar(stemIdx, branchIdx) {
        if (stemIdx === null || branchIdx === null) return { stem: '?', branch: '?', stH: '시', brH: '미상', stemIdx: null, branchIdx: null };
        return { stem: heavenlyStems[stemIdx], branch: earthlyBranches[branchIdx], stH: stemKorean[stemIdx], brH: branchKorean[branchIdx], stemIdx, branchIdx };
    }

    // 지지 합/충/형/파/해 관계 판정 (정통 명리학 - 일지 기준)
    function getBranchRelation(dayBranchIdx, targetBranchIdx) {
        const yukhap = {0:1,1:0,2:11,11:2,3:10,10:3,4:9,9:4,5:8,8:5,6:7,7:6}; // 육합: 子丑 寅亥 卯戌 辰酉 巳申 午未
        const chung  = {0:6,6:0,1:7,7:1,2:8,8:2,3:9,9:3,4:10,10:4,5:11,11:5}; // 충: 子午 丑未 寅申 卯酉 辰戌 巳亥
        const pa     = {0:9,9:0,1:4,4:1,2:11,11:2,3:6,6:3,5:8,8:5,7:10,10:7}; // 파: 子酉 丑辰 寅亥 卯午 巳申 未戌
        const hae    = {0:7,7:0,1:6,6:1,2:5,5:2,3:4,4:3,8:11,11:8,9:10,10:9}; // 해: 子未 丑午 寅巳 卯辰 申亥 酉戌
        const samhap = { '신자진': [8,0,4], '해묘미': [11,3,7], '인오술': [2,6,10], '사유축': [5,9,1] }; // 삼합

        if (dayBranchIdx === targetBranchIdx) return { type: '자형(自刑)', score: -8, label: '비화·중복' };
        for (const key in samhap) {
            const g = samhap[key];
            if (g.includes(dayBranchIdx) && g.includes(targetBranchIdx)) return { type: '삼합(三合)', score: 30, label: '강한 화합' };
        }
        if (yukhap[dayBranchIdx] === targetBranchIdx) return { type: '육합(六合)', score: 22, label: '조화' };
        if (chung[dayBranchIdx] === targetBranchIdx) return { type: '충(沖)', score: -22, label: '충돌·변동' };
        if (pa[dayBranchIdx] === targetBranchIdx) return { type: '파(破)', score: -12, label: '파열' };
        if (hae[dayBranchIdx] === targetBranchIdx) return { type: '해(害)', score: -12, label: '방해' };
        return { type: '평(平)', score: 0, label: '무난' };
    }

    function getTenGod(dayStemIdx, targetStemIdx) {
        const dayEl = Math.floor(dayStemIdx / 2); const targetEl = Math.floor(targetStemIdx / 2);
        const samePolarity = dayStemIdx % 2 === targetStemIdx % 2;
        if (dayEl === targetEl) return samePolarity ? '비견' : '겁재';
        if ((dayEl + 1) % 5 === targetEl) return samePolarity ? '식신' : '상관';
        if ((dayEl + 2) % 5 === targetEl) return samePolarity ? '편재' : '정재';
        if ((targetEl + 2) % 5 === dayEl) return samePolarity ? '편관' : '정관';
        return samePolarity ? '편인' : '정인';
    }


function nativeChart(input) {
    const chart = SolarManager.chart(input, {getYearPillar,getMonthPillar,getDayPillar});
    const raw = [chart.yearPillar,chart.monthPillar,chart.dayPillar,chart.hourPillar];
    const hidden = [[9],[5,9,7],[0,2,4],[1],[4,1,9],[2,4,6],[3,5],[5,3,1],[6,8,4],[7],[4,7,3],[8,0]];
    const pillars = raw.map((p,i) => ({position:['년주','월주','일주','시주'][i],
        value:p.stemIdx===null ? '미상' : heavenlyStems[p.stemIdx]+earthlyBranches[p.branchIdx],
        reading:p.stemIdx===null ? '출생 시각 미상' : stemKorean[p.stemIdx]+branchKorean[p.branchIdx],
        tenGod:p.stemIdx===null ? '미상' : i===2 ? '일간(본인)' : getTenGod(chart.dayPillar.stemIdx,p.stemIdx),
        hiddenStems:p.branchIdx===null ? [] : hidden[p.branchIdx].map(stem=>({stem:heavenlyStems[stem],tenGod:getTenGod(chart.dayPillar.stemIdx,stem)}))}));
    const distribution = {wood:0,fire:0,earth:0,metal:0,water:0};
    raw.filter(p=>p.stemIdx!==null).forEach(p=>{ distribution[getElementOfCharacter(heavenlyStems[p.stemIdx])]++; distribution[getElementOfCharacter(earthlyBranches[p.branchIdx])]++; });
    const start = new Date(Date.UTC(input.weekYear,input.weekMonth-1,input.weekDay));
    start.setUTCDate(start.getUTCDate()-start.getUTCDay());
    const weakest = Object.entries(distribution).sort((a,b)=>a[1]-b[1]).slice(0,2).map(e=>e[0]);
    const days = Array.from({length:7},(_,i)=>{
        const d = new Date(start); d.setUTCDate(start.getUTCDate()+i);
        const p = getDayPillar(d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate());
        const tenGod = getTenGod(chart.dayPillar.stemIdx,p.stemIdx);
        const relation = getBranchRelation(chart.dayPillar.branchIdx,p.branchIdx);
        const bonus = {'편재':25,'정재':25,'식신':18,'상관':18,'편인':10,'정인':10,'정관':12,'편관':5,'비견':8,'겁재':8};
        const score = 50+(bonus[tenGod]||0)+relation.score+[heavenlyStems[p.stemIdx],earthlyBranches[p.branchIdx]].reduce((sum,c)=>sum+(weakest.includes(getElementOfCharacter(c))?8:0),0);
        return {day:weekDays[i],date:d.toISOString().slice(0,10),score,tenGod,relation:relation.label};
    });
    const best = days.reduce((a,b)=>a.score>=b.score?a:b);
    const limits = '오행은 표면 개수이며 월령·지장간 강도를 가중하지 않습니다. 용신·격국·대운·세운은 산출하지 않습니다. 주간 점수는 오락용 자체 비교 지표이며 확률이 아닙니다.';
    return JSON.stringify({pillars,distribution,days,bestDay:best.day,basis:chart.basis,limits});
}
